    const copyText = `${BRAND_NAME} ${BUILD_VERSION} Transfer Readiness Score ${scoreId}: ${scoreState}, ${readinessScore}%. Decision ${readinessDecision}. Answer ${oneAnswer}. Risk ${riskSignal}. Next: ${nextAction}`;
