  function buildCommandEnterpriseControlPlaneBlueprint(model, autopilot) {
    const council = buildCommandCustomerNetworkLearningCouncil(model, autopilot);
    const openCount = model.openRecords.length;
    const actionCount = model.reminders.tasks.length;
    const overdueCount = model.reminders.overdue || 0;
    const evidenceScore = model.evidenceScore || 0;
    const healthScore = model.healthScore || 0;
    const weeklyScore = model.weeklyReview?.reviewScore || healthScore;
    const sourceCoverage = model.documents?.sourceCoverage || evidenceScore;
    const contractScore = model.contractScore || Math.max(1, 100 - (model.contractGaps?.length || 0) * 8);
    const totalValue = formatCompactMoney(model.totalValue);
    const firstMove = model.priorityTasks[0]?.title || autopilot.signals[0]?.record.title || "Enterprise control plane move";
    const backendFoundation = Math.max(1, Math.min(100, Math.round(council.proofQuality * 0.24 + sourceCoverage * 0.22 + evidenceScore * 0.18 + Math.max(0, 100 - (model.evidenceGaps?.length || 0) * 4) * 0.16 + 10)));
    const tenantOperations = Math.max(1, Math.min(100, Math.round(healthScore * 0.24 + weeklyScore * 0.22 + Math.max(0, 100 - overdueCount * 2) * 0.2 + council.tenantConsent * 0.18 + 10)));
    const billingAccess = Math.max(1, Math.min(100, Math.round(contractScore * 0.28 + council.tenantConsent * 0.2 + council.privacyBoundary * 0.18 + Math.max(0, 100 - (model.contractGaps?.length || 0) * 7) * 0.16 + 10)));
    const supportOperations = Math.max(1, Math.min(100, Math.round(Math.max(0, 100 - overdueCount * 3) * 0.28 + weeklyScore * 0.22 + healthScore * 0.18 + council.reuseReadiness * 0.16 + 10)));
    const auditEvidence = Math.max(1, Math.min(100, Math.round(sourceCoverage * 0.28 + evidenceScore * 0.26 + council.proofQuality * 0.2 + council.privacyBoundary * 0.16 + 6)));
    const rolloutControl = Math.max(1, Math.min(100, Math.round(council.councilScore * 0.22 + council.reuseReadiness * 0.22 + backendFoundation * 0.18 + tenantOperations * 0.16 + supportOperations * 0.12 + 6)));
    const planeScore = Math.max(1, Math.min(100, Math.round((backendFoundation + tenantOperations + billingAccess + supportOperations + auditEvidence + rolloutControl) / 6)));
    const planeState = planeScore >= 84 && overdueCount === 0 ? "Enterprise control plane can move into private backend execution" : planeScore >= 72 ? "Enterprise control plane is mapped, with a few launch rails still needing proof" : "Enterprise control plane should stay in blueprint mode until the rails are stronger";
    const controlLanes = [
      ["Backend foundation", `${backendFoundation}%`, "API, database, auth, import, tenant isolation, and rollback proof are the first private-repo rail.", backendFoundation >= 80 ? "green" : "amber"],
      ["Tenant operations", `${tenantOperations}%`, `${openCount} open records and ${actionCount} actions shape daily operating load.`, tenantOperations >= 80 ? "teal" : "blue"],
      ["Billing access", `${billingAccess}%`, `Contract posture ${contractScore}% with ${model.contractGaps?.length || 0} contract gaps before paid pilot.`, billingAccess >= 80 ? "green" : "amber"],
      ["Support operations", `${supportOperations}%`, `${overdueCount} overdue follow-ups decide support pressure before SLA commitments.`, supportOperations >= 78 ? "blue" : "red"],
      ["Audit evidence", `${auditEvidence}%`, `Evidence ${evidenceScore}% and source coverage ${sourceCoverage}% define launch proof.`, auditEvidence >= 80 ? "green" : "amber"],
      ["Rollout control", `${rolloutControl}%`, `Council score ${council.councilScore}% keeps release, learning, and rollback connected.`, rolloutControl >= 80 ? "teal" : "blue"],
    ];
    const blueprintStages = [
      { step: "01", label: "Identity and access", signal: "User accounts, roles, invites, revokes, admin grants, and session boundaries become backend-owned.", owner: "Security", tone: "green" },
      { step: "02", label: "Tenant data plane", signal: "Records, imports, attachments, evidence, and tenant-local memory are isolated before live data arrives.", owner: "Backend", tone: "blue" },
      { step: "03", label: "Billing access gate", signal: "Plan, seats, invoice state, grace rules, checkout, and paid-pilot access lock into one control gate.", owner: "Finance", tone: "amber" },
      { step: "04", label: "Support SLA", signal: "Support routing, first-response promises, escalation owners, closeout receipts, and knowledge gaps stay visible.", owner: "Support", tone: "teal" },
      { step: "05", label: "Audit evidence trail", signal: "Every import, role change, export, approval, proof upload, and release decision writes an audit event.", owner: "Governance", tone: "green" },
      { step: "06", label: "Rollout control", signal: "Staging, rollback, release gates, pilot signoff, tenant notices, and learning council decisions move together.", owner: "Release", tone: "blue" },
    ];
    const launchGates = [
      ["Private repo", "Required", "Create the production repository, issue wave, branch protection, and first backend PR.", "amber"],
      ["Staging tenant", "Required", "Deploy staging with seed data, migrations, smoke tests, backup proof, and rollback rehearsal.", "blue"],
      ["Paid pilot access", "Mapped", "Connect billing state to tenant access before live pilot users enter the workspace.", billingAccess >= 78 ? "green" : "amber"],
      ["Audit-ready release", "Mapped", "Keep every release, approval, import, role change, and learning decision exportable.", auditEvidence >= 80 ? "green" : "amber"],
    ];
    const nextAction = planeScore >= 84 && overdueCount === 0
      ? "Open the private backend execution lane and turn the blueprint into issues, owners, acceptance checks, and staging proof."
      : planeScore >= 72
        ? "Use the blueprint to open only the strongest backend, tenant, billing, support, audit, and rollout issues first."
        : "Keep this as an admin blueprint and repair evidence, overdue pressure, and contract gaps before private repo execution.";
    const planeId = `${BUILD_VERSION.toUpperCase()}-ENTERPRISE-CONTROL-PLANE`;
    const copyText = `${BRAND_NAME} ${BUILD_VERSION} Enterprise Control Plane Blueprint ${planeId}: ${planeState}. Score ${planeScore}%. Backend ${backendFoundation}%. Tenant ops ${tenantOperations}%. Billing ${billingAccess}%. Support ${supportOperations}%. Audit ${auditEvidence}%. Rollout ${rolloutControl}%. Value context ${totalValue}. First move: ${compactText(firstMove, 96)}. Next: ${nextAction}`;
    return { auditEvidence, billingAccess, blueprintStages, backendFoundation, controlLanes, copyText, launchGates, nextAction, planeId, planeScore, planeState, rolloutControl, supportOperations, tenantOperations };
  }

