  function buildCommandCustomerLearningSandbox(model, autopilot) {
    const council = buildCommandCustomerNetworkLearningCouncil(model, autopilot);
    const roleHome = buildCommandRoleBasedHomeConsole(model, autopilot);
    const actionCount = model.reminders.tasks.length;
    const overdueCount = model.reminders.overdue || 0;
    const evidenceScore = model.evidenceScore || 0;
    const healthScore = model.healthScore || 0;
    const sourceCoverage = model.documents?.sourceCoverage || evidenceScore;
    const firstMove = model.priorityTasks[0]?.title || autopilot.signals[0]?.record.title || "Sandbox the next customer lesson";
    const scenarioFit = Math.max(1, Math.min(100, Math.round(roleHome.calmScore * 0.24 + council.reuseReadiness * 0.24 + healthScore * 0.18 + Math.max(0, 100 - actionCount * 0.2) * 0.16 + 8)));
    const proofSafety = Math.max(1, Math.min(100, Math.round(council.proofQuality * 0.28 + council.privacyBoundary * 0.26 + sourceCoverage * 0.2 + evidenceScore * 0.16 + 6)));
    const replayQuality = Math.max(1, Math.min(100, Math.round(council.councilScore * 0.24 + scenarioFit * 0.22 + proofSafety * 0.22 + roleHome.accessFit * 0.18 + 6)));
    const releaseHold = Math.max(1, Math.min(100, Math.round(Math.max(0, 100 - overdueCount * 2.2) * 0.28 + proofSafety * 0.24 + council.tenantConsent * 0.2 + roleHome.homeFocus * 0.16 + 6)));
    const sandboxScore = Math.max(1, Math.min(100, Math.round(scenarioFit * 0.25 + proofSafety * 0.28 + replayQuality * 0.24 + releaseHold * 0.23)));
    const sandboxState = sandboxScore >= 84 && overdueCount === 0 ? "Sandbox can promote one observe-only lesson" : sandboxScore >= 72 ? "Sandbox can test lessons with approval holds" : "Sandbox should stay in preview until proof and pressure improve";
    const controls = [
      ["Scenario fit", `${scenarioFit}%`, "Sample tenant situations are matched before any live guidance changes.", scenarioFit >= 80 ? "green" : "amber"],
      ["Proof safety", `${proofSafety}%`, `Evidence ${evidenceScore}% and source coverage ${sourceCoverage}% decide whether a lesson is safe to test.`, proofSafety >= 80 ? "teal" : "blue"],
      ["Replay quality", `${replayQuality}%`, "Projected benefit must be checked against council, role, and access signals.", replayQuality >= 80 ? "green" : "amber"],
      ["Release hold", `${releaseHold}%`, `${overdueCount} overdue items keep unsafe lessons in observe-only mode.`, releaseHold >= 80 ? "blue" : "red"],
    ];
    const scenarios = [
      ["Adoption recovery", "Replay whether overdue pressure and low movement should produce a calmer success script.", "Customer Success", overdueCount ? "amber" : "green"],
      ["Renewal confidence", "Test whether proof, sponsor response, billing posture, and support calm justify renewal guidance.", "Management", council.proofQuality >= 80 ? "green" : "blue"],
      ["Support escalation", "Check repeated questions and evidence gaps before a support playbook reaches live users.", "Support", "teal"],
      ["Bid decision posture", "Try bid, no-bid, hold, or proof-repair guidance against tender scenarios without touching records.", "Commercial", "amber"],
      ["Governance evidence", "Confirm anonymization, consent, and audit trail before any cross-organization learning moves.", "Governance", council.privacyBoundary >= 80 ? "green" : "red"],
    ];
    const gates = [
      ["1", "Pick sample case", "Use a synthetic tenant pattern or redacted record shape, not live customer data.", "green"],
      ["2", "Remove private detail", "Strip client names, owner names, values, attachments, and raw workbook text.", "blue"],
      ["3", "Replay guidance", "Run the candidate lesson as observe-only and compare projected movement with risk.", "teal"],
      ["4", "Decide boundary", "Promote to approval, hold for proof, keep tenant-local, or retire as an anti-pattern.", "amber"],
    ];
    const nextAction = sandboxScore >= 84 && overdueCount === 0
      ? "Promote one observe-only lesson into council approval and keep the release reversible."
      : sandboxScore >= 72
        ? "Run two sandbox cases, hold weak proof, and keep live guidance unchanged."
        : "Repair proof, overdue pressure, and privacy confidence before any sandbox result can graduate.";
    const sandboxId = `${BUILD_VERSION.toUpperCase()}-CUSTOMER-LEARNING-SANDBOX`;
    const copyText = `${BRAND_NAME} ${BUILD_VERSION} Customer Learning Sandbox ${sandboxId}: ${sandboxState}. Sandbox ${sandboxScore}%. Scenario fit ${scenarioFit}%. Proof safety ${proofSafety}%. Replay ${replayQuality}%. Release hold ${releaseHold}%. First move: ${compactText(firstMove, 96)}. Next: ${nextAction}`;
    return { controls, copyText, gates, nextAction, proofSafety, releaseHold, replayQuality, sandboxId, sandboxScore, sandboxState, scenarioFit, scenarios };
  }

