  function buildCommandStagingProofSprintBoard(model, autopilot) {
    const gate = buildCommandSandboxGraduationGate(model, autopilot);
    const wave = buildCommandPrivateBackendIssueWave(model, autopilot);
    const actionCount = model.reminders.tasks.length;
    const overdueCount = model.reminders.overdue || 0;
    const evidenceScore = model.evidenceScore || 0;
    const sourceCoverage = model.documents?.sourceCoverage || evidenceScore;
    const firstMove = model.priorityTasks[0]?.title || autopilot.signals[0]?.record.title || "Run the first staging smoke check";
    const smokeReadiness = Math.max(1, Math.min(100, Math.round(wave.stagingProof * 0.28 + wave.acceptanceProof * 0.22 + sourceCoverage * 0.2 + Math.max(0, 100 - overdueCount * 1.8) * 0.16 + 6)));
    const rollbackConfidence = Math.max(1, Math.min(100, Math.round(gate.retirementSafety * 0.28 + wave.blockerPressure * 0.24 + gate.approvalConfidence * 0.18 + evidenceScore * 0.14 + 6)));
    const pilotEvidence = Math.max(1, Math.min(100, Math.round(gate.graduationReadiness * 0.24 + wave.acceptanceProof * 0.24 + gate.tenantBoundary * 0.18 + sourceCoverage * 0.18 + 6)));
    const releaseCalm = Math.max(1, Math.min(100, Math.round(Math.max(0, 100 - actionCount * 0.2) * 0.24 + Math.max(0, 100 - overdueCount * 2.2) * 0.24 + wave.ownerClarity * 0.2 + gate.gateScore * 0.16 + 6)));
    const sprintScore = Math.max(1, Math.min(100, Math.round(smokeReadiness * 0.26 + rollbackConfidence * 0.24 + pilotEvidence * 0.26 + releaseCalm * 0.24)));
    const readyCount = Math.max(1, Math.min(6, Math.round(sprintScore / 18)));
    const repairCount = Math.max(1, Math.min(6, Math.ceil((model.evidenceGaps.length + model.contractGaps.length + overdueCount) / 22)));
    const blockerCount = Math.max(1, Math.min(5, Math.ceil(Math.max(0, 88 - releaseCalm) / 14)));
    const rehearsalCount = rollbackConfidence >= 82 ? 2 : 1;
    const sprintState = sprintScore >= 84 && overdueCount === 0 ? "Staging sprint can move toward pilot signoff" : sprintScore >= 72 ? "Staging sprint can run with proof holds" : "Keep staging in repair until smoke, rollback, and evidence improve";
    const controls = [
      ["Smoke readiness", `${smokeReadiness}%`, "Login, import, edit, reminders, reports, and learning gates are checked before pilot movement.", smokeReadiness >= 80 ? "green" : "amber"],
      ["Rollback confidence", `${rollbackConfidence}%`, "Every staging change has a rehearsal, owner, restore note, and retire path.", rollbackConfidence >= 80 ? "teal" : "blue"],
      ["Pilot evidence", `${pilotEvidence}%`, "Screenshots, logs, acceptance notes, and boundary receipts become launch proof.", pilotEvidence >= 80 ? "green" : "amber"],
      ["Release calm", `${releaseCalm}%`, `${overdueCount} overdue items and ${actionCount} actions decide whether staging stays quiet enough.`, releaseCalm >= 80 ? "blue" : "red"],
    ];
    const lanes = [
      ["Stage smoke", `${readyCount} ready`, "Run only the checks with owner, expected result, and evidence target attached.", readyCount >= 4 ? "green" : "amber"],
      ["Prove rollback", `${rehearsalCount} rehearsals`, "Restore, revoke, disable, or revert must be practiced before pilot signoff.", rollbackConfidence >= 80 ? "teal" : "blue"],
      ["Capture evidence", `${pilotEvidence}% proof`, "Each passed check creates a screenshot, log, note, or receipt for the pilot pack.", pilotEvidence >= 80 ? "green" : "amber"],
      ["Hold blockers", `${blockerCount} holds`, "Staging stays blocked where owner, acceptance, evidence, or rollback is unclear.", blockerCount <= 2 ? "blue" : "red"],
    ];
    const checks = [
      { key: "STG-01", title: "Login and role access", owner: "Security", expected: "Admin, Commercial, Operations, Management, Governance, and Support enter the correct home.", proof: "Access screenshot and denied-route receipt", tone: "green" },
      { key: "STG-02", title: "Import and edit records", owner: "Operations", expected: "Workbook import, row edit, status change, and rollback file are visible.", proof: "Import count plus rollback file name", tone: "blue" },
      { key: "STG-03", title: "Reminder routing", owner: "Operations", expected: "Overdue, missing data, negotiation, and high-value reminders route to the right lanes.", proof: "Reminder board screenshot", tone: overdueCount ? "amber" : "green" },
      { key: "STG-04", title: "Report export", owner: "Management", expected: "Weekly pack, reports room, and client pressure view print without broken layout.", proof: "PDF or print-preview receipt", tone: "teal" },
      { key: "STG-05", title: "Learning boundary gate", owner: "Governance", expected: "Sandbox learning can graduate, stay tenant-local, repair, or retire with a decision receipt.", proof: "Graduation gate copy receipt", tone: gate.gateScore >= 80 ? "green" : "amber" },
      { key: "STG-06", title: "Rollback rehearsal", owner: "Release", expected: "Disable the new guidance, restore the previous route, and record owner acceptance.", proof: "Rollback note and owner signoff", tone: rollbackConfidence >= 80 ? "blue" : "red" },
    ];
    const receipts = [
      ["1", "Open sprint", "Name the staging tenant, owner, smoke list, and rollback owner before testing starts.", "green"],
      ["2", "Run and attach", "Every pass or fail attaches screenshot, log, note, or export proof.", "blue"],
      ["3", "Decide pilot gate", "Go, hold, repair, rollback, or retire is chosen before launch movement.", "teal"],
      ["4", "Seal evidence", "The final sprint pack becomes the pilot signoff receipt and launch audit trail.", "amber"],
    ];
    const nextAction = sprintScore >= 84 && overdueCount === 0
      ? "Run the full staging proof sprint and prepare pilot signoff from the evidence pack."
      : sprintScore >= 72
        ? "Run the safest smoke checks, attach proof, and keep blocker lanes visible until rollback is rehearsed."
        : "Hold pilot movement, repair smoke proof and rollback confidence, then reopen the staging sprint.";
    const sprintId = `${BUILD_VERSION.toUpperCase()}-STAGING-PROOF-SPRINT`;
    const copyText = `${BRAND_NAME} ${BUILD_VERSION} Staging Proof Sprint Board ${sprintId}: ${sprintState}. Score ${sprintScore}%. Smoke ${smokeReadiness}%. Rollback ${rollbackConfidence}%. Pilot evidence ${pilotEvidence}%. Release calm ${releaseCalm}%. Ready ${readyCount}, repair ${repairCount}, blockers ${blockerCount}, rehearsals ${rehearsalCount}. First move: ${compactText(firstMove, 96)}. Next: ${nextAction}`;
    return { checks, controls, copyText, lanes, nextAction, pilotEvidence, receipts, releaseCalm, repairCount, rollbackConfidence, smokeReadiness, sprintId, sprintScore, sprintState };
  }

