  function buildCommandPilotLaunchDecisionRoom(model, autopilot) {
    const signoff = buildCommandPilotSignoffEvidencePack(model, autopilot);
    const tenantAdmin = buildCommandFirstTenantAdminConsole(model, autopilot);
    const safety = buildCommandLiveLearningSafetyMonitor(model, autopilot);
    const sprint = buildCommandStagingProofSprintBoard(model, autopilot);
    const rollbackConsole = buildCommandLearningRollbackConsole(model, autopilot);
    const actionCount = model.reminders.tasks.length;
    const overdueCount = model.reminders.overdue || 0;
    const evidenceScore = model.evidenceScore || 0;
    const sourceCoverage = model.documents?.sourceCoverage || evidenceScore;
    const firstTask = model.priorityTasks[0] || {};
    const firstMove = firstTask.title || autopilot.signals[0]?.record.title || "Open the pilot launch decision";
    const launchDate = firstTask.dueDate || firstTask.due || firstTask.date || "Next sponsor review";
    const launchReadiness = Math.max(1, Math.min(100, Math.round(signoff.packScore * 0.28 + tenantAdmin.adminScore * 0.24 + sprint.sprintScore * 0.2 + Math.max(0, 100 - overdueCount * 1.7) * 0.14 + 6)));
    const decisionClarity = Math.max(1, Math.min(100, Math.round(signoff.sponsorConfidence * 0.25 + signoff.signoffCount * 7 + tenantAdmin.userRoster * 0.18 + Math.max(0, 100 - actionCount * 0.12) * 0.14 + 7)));
    const riskControl = Math.max(1, Math.min(100, Math.round(signoff.riskSeal * 0.24 + safety.monitorScore * 0.24 + rollbackConsole.rollbackWatch * 0.2 + tenantAdmin.supportAudit * 0.16 + 6)));
    const pilotProof = Math.max(1, Math.min(100, Math.round(signoff.evidenceIndex * 0.26 + sprint.pilotEvidence * 0.24 + safety.outcomeProof * 0.2 + sourceCoverage * 0.14 + 6)));
    const decisionScore = Math.max(1, Math.min(100, Math.round(launchReadiness * 0.26 + decisionClarity * 0.24 + riskControl * 0.26 + pilotProof * 0.24)));
    const goCount = decisionScore >= 84 && signoff.signoffCount >= 5 && overdueCount === 0 && tenantAdmin.billingState !== "Hold" ? 1 : 0;
    const holdCount = Math.max(1, Math.min(6, Math.ceil(Math.max(0, 88 - launchReadiness) / 12) + (tenantAdmin.billingState === "Hold" ? 1 : 0)));
    const repairCount = Math.max(1, Math.min(8, signoff.exceptionCount + Math.ceil(Math.max(0, 82 - pilotProof) / 14)));
    const rollbackCount = Math.max(1, Math.min(5, rollbackConsole.rollbackLocks + (riskControl < 76 ? 1 : 0)));
    const noGoTriggers = Math.max(0, Math.min(5, (decisionScore < 66 ? 1 : 0) + (safety.monitorScore < 70 ? 1 : 0) + (signoff.signoffCount < 4 ? 1 : 0) + (tenantAdmin.billingState === "Hold" ? 1 : 0) + (pilotProof < 68 ? 1 : 0)));
    const launchOwner = tenantAdmin.billingState === "Hold" ? "Admin + Billing" : signoff.signoffCount >= 5 ? "Sponsor + Admin" : "Governance + Release";
    const decisionState = goCount
      ? "Pilot launch can move to a go decision"
      : noGoTriggers >= 2
        ? "No-go until proof, safety, billing, and owner acceptance improve"
        : decisionScore >= 72
          ? "Pilot launch can move with visible holds and repair path"
          : "Hold pilot launch until signoff, safety, proof, and rollback are calmer";
    const controls = [
      ["Launch readiness", `${launchReadiness}%`, "Signoff, tenant admin, staging proof, and overdue pressure decide the go posture.", launchReadiness >= 80 ? "green" : "amber"],
      ["Decision clarity", `${decisionClarity}%`, "Sponsor ask, signatures, owner, date, support, and billing route stay visible before the decision.", decisionClarity >= 80 ? "teal" : "blue"],
      ["Risk control", `${riskControl}%`, "Safety monitor, rollback watch, support audit, and risk seal decide whether launch remains reversible.", riskControl >= 80 ? "green" : "red"],
      ["Pilot proof", `${pilotProof}%`, "Evidence index, staging proof, outcome proof, and source coverage become the launch proof base.", pilotProof >= 80 ? "blue" : "amber"],
    ];
    const lanes = [
      ["Go decision", goCount ? "Ready" : "Not yet", "Move only when signoff, tenant admin, safety, billing, and proof are all calm.", goCount ? "green" : "amber"],
      ["Hold decision", `${holdCount} holds`, "Keep visible holds for missing billing, owner, date, support, evidence, or acceptance details.", holdCount <= 2 ? "teal" : "blue"],
      ["Repair path", `${repairCount} repairs`, "Turn exceptions into owner tasks before launch day, instead of hiding them in the meeting notes.", repairCount <= 3 ? "green" : "amber"],
      ["Rollback option", `${rollbackCount} locks`, "A reversible route stays named before any real pilot user depends on the workflow.", rollbackCount <= 2 ? "blue" : "red"],
    ];
    const decisions = [
      ["Go", goCount ? "Available" : "Wait", "Pilot can launch only when six signoff roles, admin, billing, safety, and proof are aligned.", "Launch receipt", goCount ? "green" : "amber"],
      ["Hold", `${holdCount} holds`, "Use hold when the pilot is valuable but an owner, date, proof, or billing route is weak.", "Hold log", holdCount <= 2 ? "teal" : "blue"],
      ["Repair", `${repairCount} repairs`, "Route each weak point to an owner with proof target, due date, and return gate.", "Repair queue", repairCount <= 3 ? "green" : "amber"],
      ["Rollback", `${rollbackCount} locks`, "Keep rollback, revoke, retire, and support fallback named before launch begins.", "Rollback receipt", riskControl >= 78 ? "blue" : "red"],
      ["No-go", `${noGoTriggers} triggers`, "No-go stays explicit when evidence, billing, owner acceptance, or safety is not credible.", "No-go reason", noGoTriggers ? "red" : "green"],
      ["Launch owner", launchOwner, `Own the final decision, first review, support route, and ${compactText(launchDate, 32)} checkpoint.`, "Owner/date proof", decisionClarity >= 78 ? "green" : "amber"],
    ];
    const receipts = [
      ["1", "Decision opened", "Pilot scope, owner, date, tenant, decision type, and first review checkpoint are named.", "green"],
      ["2", "Evidence basis", "Signoff pack, staging sprint, tenant admin, safety monitor, and rollback console are attached.", "blue"],
      ["3", "Owner and date", "Every hold or repair has accountable owner, due date, proof target, and return gate.", "teal"],
      ["4", "Launch receipt", "Go, hold, repair, rollback, or no-go is sealed with proof before launch day movement.", "amber"],
    ];
    const nextAction = goCount
      ? "Seal the go receipt, keep rollback live, and schedule the first sponsor review."
      : noGoTriggers >= 2
        ? "Name the no-go reasons, repair proof and billing, then reopen the decision room."
        : decisionScore >= 72
          ? "Pick hold or repair, assign owners and dates, and keep rollback ready before launch."
          : "Keep the pilot in preparation mode, repair signoff and safety proof, then return to decision.";
    const roomId = `${BUILD_VERSION.toUpperCase()}-PILOT-LAUNCH-DECISION-ROOM`;
    const copyText = `${BRAND_NAME} ${BUILD_VERSION} Pilot Launch Decision Room ${roomId}: ${decisionState}. Score ${decisionScore}%. Launch ${launchReadiness}%. Decision ${decisionClarity}%. Risk ${riskControl}%. Proof ${pilotProof}%. Go ${goCount}, hold ${holdCount}, repair ${repairCount}, rollback ${rollbackCount}, no-go triggers ${noGoTriggers}. Owner ${launchOwner}. Date ${launchDate}. First move: ${compactText(firstMove, 96)}. Next: ${nextAction}`;
    return { controls, copyText, decisionClarity, decisionScore, decisions, decisionState, goCount, holdCount, lanes, launchDate, launchOwner, launchReadiness, nextAction, noGoTriggers, pilotProof, receipts, repairCount, riskControl, rollbackCount, roomId };
  }

