  function buildCommandTenantLaunchDayRunbook(model, autopilot) {
    const decision = buildCommandPilotLaunchDecisionRoom(model, autopilot);
    const tenantAdmin = buildCommandFirstTenantAdminConsole(model, autopilot);
    const safety = buildCommandLiveLearningSafetyMonitor(model, autopilot);
    const signoff = buildCommandPilotSignoffEvidencePack(model, autopilot);
    const sprint = buildCommandStagingProofSprintBoard(model, autopilot);
    const actionCount = model.reminders.tasks.length;
    const overdueCount = model.reminders.overdue || 0;
    const evidenceScore = model.evidenceScore || 0;
    const sourceCoverage = model.documents?.sourceCoverage || evidenceScore;
    const firstTask = model.priorityTasks[0] || {};
    const firstMove = firstTask.title || autopilot.signals[0]?.record.title || "Run the first tenant launch check";
    const launchDate = decision.launchDate || firstTask.dueDate || firstTask.due || firstTask.date || "Launch day";
    const accessCheck = Math.max(1, Math.min(100, Math.round(tenantAdmin.userRoster * 0.28 + tenantAdmin.roleControl * 0.24 + signoff.operatingAcceptance * 0.2 + Math.max(0, 100 - overdueCount * 1.6) * 0.12 + 6)));
    const supportWatch = Math.max(1, Math.min(100, Math.round(tenantAdmin.supportAudit * 0.28 + safety.supportPressure * 0.24 + decision.riskControl * 0.18 + Math.max(0, 100 - actionCount * 0.12) * 0.14 + 6)));
    const billingProof = Math.max(1, Math.min(100, Math.round(tenantAdmin.billingPosture * 0.3 + signoff.sponsorConfidence * 0.2 + decision.decisionClarity * 0.18 + (tenantAdmin.billingState === "Ready" ? 12 : tenantAdmin.billingState === "Review" ? 6 : 0))));
    const auditExport = Math.max(1, Math.min(100, Math.round(tenantAdmin.supportAudit * 0.22 + signoff.evidenceIndex * 0.22 + sprint.pilotEvidence * 0.2 + sourceCoverage * 0.2 + 6)));
    const runbookScore = Math.max(1, Math.min(100, Math.round(accessCheck * 0.27 + supportWatch * 0.25 + billingProof * 0.23 + auditExport * 0.25)));
    const accessSteps = accessCheck >= 82 ? 6 : accessCheck >= 70 ? 4 : 3;
    const supportChecks = supportWatch >= 82 ? 5 : supportWatch >= 70 ? 4 : 3;
    const billingChecks = tenantAdmin.billingState === "Ready" ? 4 : tenantAdmin.billingState === "Review" ? 3 : 2;
    const auditReceipts = Math.max(4, Math.min(12, Math.ceil(auditExport / 12) + signoff.signoffCount));
    const holdItems = Math.max(1, Math.min(8, decision.holdCount + Math.ceil(Math.max(0, 82 - runbookScore) / 12)));
    const runbookState = runbookScore >= 84 && decision.noGoTriggers === 0 && tenantAdmin.billingState === "Ready"
      ? "Tenant launch day can run from the runbook"
      : runbookScore >= 72
        ? "Tenant launch day can run with visible holds"
        : "Keep launch day in rehearsal until access, support, billing, and audit proof improve";
    const controls = [
      ["Access check", `${accessCheck}%`, "Users, roles, first room, revoke route, and denied-access proof are checked before users enter.", accessCheck >= 80 ? "green" : "amber"],
      ["Support watch", `${supportWatch}%`, "Support contact, response promise, escalation route, and question capture are visible during day one.", supportWatch >= 80 ? "teal" : "blue"],
      ["Billing proof", tenantAdmin.billingState, "Plan, seats, invoice trigger, grace rule, and access lock are reviewed before launch movement.", billingProof >= 80 ? "green" : "amber"],
      ["Audit export", `${auditExport}%`, "Launch actions, signoffs, access checks, support notes, and evidence receipts stay export-ready.", auditExport >= 80 ? "blue" : "red"],
    ];
    const lanes = [
      ["Open tenant", `${accessSteps} access checks`, "Confirm admin, commercial, operations, management, governance, and support starts.", accessSteps >= 5 ? "green" : "amber"],
      ["Watch support", `${supportChecks} watch points`, "Log first login question, first movement question, escalation owner, SLA note, and closeout route.", supportChecks >= 4 ? "teal" : "blue"],
      ["Confirm billing", `${billingChecks} proofs`, "Capture plan, seat count, invoice trigger, grace posture, and access lock before paid pilot.", billingChecks >= 4 ? "green" : "amber"],
      ["Export audit", `${auditReceipts} receipts`, "Export the launch trail after access, first movement, support watch, and billing proof are checked.", auditReceipts >= 8 ? "blue" : "red"],
    ];
    const runbook = [
      ["Open workspace", "T-30 min", "Admin verifies tenant home, active users, role templates, denied routes, and first room.", "Access screenshot", accessCheck >= 78 ? "green" : "amber"],
      ["Confirm first movement", "T+15 min", "Operations opens the first record, confirms owner, due date, proof path, and reminder lane.", "Movement receipt", decision.launchReadiness >= 78 ? "teal" : "blue"],
      ["Support watch", "T+30 min", "Support records questions, escalation route, first-response promise, and knowledge note.", "Support log", supportWatch >= 78 ? "green" : "amber"],
      ["Billing and seats", "T+45 min", "Admin confirms plan, seats, invoice trigger, grace rule, and access lock posture.", "Billing proof", billingProof >= 78 ? "blue" : "amber"],
      ["Safety and rollback", "T+60 min", "Governance checks safety monitor, rollback lock, tenant boundary, and no-go triggers.", "Rollback note", safety.monitorScore >= 78 ? "teal" : "red"],
      ["First review booked", "End of day", `Sponsor review is booked against ${compactText(launchDate, 34)} with outcome proof target and owner.`, "Review invite", decision.decisionClarity >= 78 ? "green" : "amber"],
    ];
    const receipts = [
      ["1", "Launch opened", "Tenant, owner, date, access scope, support contact, and decision state are recorded.", "green"],
      ["2", "Day-one checked", "Access, first movement, support question, billing proof, and safety watch are checked.", "blue"],
      ["3", "Holds routed", "Any weak owner, date, proof, billing, support, or rollback item receives a repair owner.", "teal"],
      ["4", "Audit exported", "The launch trail is export-ready for sponsor, admin, governance, and build handoff.", "amber"],
    ];
    const nextAction = runbookScore >= 84 && decision.noGoTriggers === 0 && tenantAdmin.billingState === "Ready"
      ? "Run launch day from the six-step runbook and export the audit receipt after first movement."
      : runbookScore >= 72
        ? "Run the access and support checks, hold weak billing or proof items, and export the partial audit trail."
        : "Keep launch in rehearsal, repair access and billing proof, then reopen the runbook.";
    const runbookId = `${BUILD_VERSION.toUpperCase()}-TENANT-LAUNCH-DAY-RUNBOOK`;
    const copyText = `${BRAND_NAME} ${BUILD_VERSION} Tenant Launch Day Runbook ${runbookId}: ${runbookState}. Score ${runbookScore}%. Access ${accessCheck}%. Support ${supportWatch}%. Billing ${tenantAdmin.billingState}/${billingProof}%. Audit ${auditExport}%. Holds ${holdItems}. Owner ${decision.launchOwner}. Date ${launchDate}. First move: ${compactText(firstMove, 96)}. Next: ${nextAction}`;
    return { accessCheck, accessSteps, auditExport, auditReceipts, billingChecks, billingProof, controls, copyText, holdItems, lanes, launchDate, nextAction, receipts, runbook, runbookId, runbookScore, runbookState, supportChecks, supportWatch };
  }

