    const guardrailReceipt = score(canaryWatch.privacyGuard * 0.24 + gate.tenantSafety * 0.2 + release.tenantBoundary * 0.18 + sponsorProof.buyerSafeProof * 0.16 + safeScore(release.tenantOnlyCount, 12) * 0.1 + 8);
