  function buildWebhookTestEvidencePack(webhookBlueprint, membership, stats, company) {
    const generatedOn = new Date();
    const stamp = generatedOn.toISOString().slice(0, 10).replace(/-/g, "");
    const companyName = company.name || "Pilot company";
    const tenantSlug = companyName.replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "").toLowerCase() || "tenant";
    const activeSeats = stats.seats || state.data.users.filter((user) => user.companyId === state.user.companyId).length;
    const evidencePackId = `PD-WEBHOOK-EVID-${stamp}-${String(membership.seats).padStart(3, "0")}`;
    const testClock = `${stamp}T101500Z`;
    const testSecretRef = `test_secret_${tenantSlug.slice(0, 12) || "tenant"}`;
    const samplePayloads = webhookBlueprint.eventRows.map((row, index) => {
      const eventId = `evt_test_${stamp}_${String(index + 1).padStart(2, "0")}`;
      const objectId = row.event.includes("invoice")
        ? `in_${tenantSlug.slice(0, 10)}_${index + 1}`
        : row.event.includes("subscription")
          ? `sub_${tenantSlug.slice(0, 10)}_${index + 1}`
          : `cs_${tenantSlug.slice(0, 10)}_${index + 1}`;
      return {
        eventId,
        eventType: row.event,
        fixtureFile: `${row.event.replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "").toLowerCase()}-payload.json`,
        objectId,
        signatureStatus: "accepted",
        idempotencyKey: row.idempotencyKey,
        expectedHttp: "200 accepted",
        expectedAudit: row.auditEvent,
        accessEffect: row.accessEffect,
        tone: row.tone,
      };
    });
    const signatureProofRows = [
      ["Valid signed body", "200 accepted", "Raw body matches timestamped test signature; event can enter idempotency ledger.", "green"],
      ["Tampered JSON body", "401 rejected", "Signature must fail when amount, tenant, or event type is modified after signing.", "red"],
      ["Stale timestamp", "401 rejected", `Reject payload outside ${webhookBlueprint.packet.signatureWindowSeconds}s tolerance.`, "amber"],
      ["Missing signature", "401 rejected", "Provider endpoint must never parse or mutate state without a signature header.", "red"],
      ["Wrong tenant mapping", "400 rejected", "Provider customer that cannot map to the current company is denied before side effects.", "blue"],
    ];
    const replayProofRows = [
      ["First delivery", "Processed", "Event writes invoice/subscription state, access effect, and audit envelope.", "green"],
      ["Immediate replay", "Replay acknowledged", "Same provider_event_id returns safe success and writes replay_seen audit only.", "amber"],
      ["Out-of-order update", "Held for latest timestamp", "Older subscription update cannot overwrite newer provider state.", "blue"],
      ["Internal failure retry", "Queued retry", "Database or audit writer failure leaves event unprocessed for provider retry.", "red"],
    ];
    const accessTransitionRows = [
      ["Checkout success", "Open -> Active", "Unlock workspace, paid admin rooms, and membership seat controls.", "green"],
      ["Invoice failed", "Active -> Grace", "Keep frontline work open but hold upgrades and new paid seats.", "amber"],
      ["Invoice paid", "Grace -> Active", "Clear warnings, update renewal date, and keep manager rooms available.", "teal"],
      ["Cancellation", "Grace -> Read/export", "Stop edits after grace while keeping archive, audit, and export access.", "red"],
      ["Seat update", "Active -> Reconcile", `${activeSeats}/${membership.seats} active users checked against plan limit.`, activeSeats <= membership.seats ? "green" : "red"],
    ];
    const auditEvidenceRows = samplePayloads.map((payload, index) => ({
      auditId: `audit_billing_${stamp}_${String(index + 1).padStart(2, "0")}`,
      eventId: payload.eventId,
      eventType: payload.eventType,
      outcome: payload.expectedHttp,
      beforeState: index === 0 ? "open" : "active",
      afterState: payload.eventType.includes("failed") ? "grace" : payload.eventType.includes("deleted") ? "read_export" : "active",
      proofFile: `audit-${payload.fixtureFile}`,
      tone: payload.tone,
    }));
    const evidenceFiles = [
      ["webhook-test-payloads.json", `${samplePayloads.length} provider payload fixtures with event ids, object ids, tenant mapping, and expected outcomes.`, "blue"],
      ["webhook-signature-proof.json", `${signatureProofRows.length} valid, stale, tampered, missing, and wrong-tenant signature cases.`, "red"],
      ["webhook-replay-proof.json", `${replayProofRows.length} idempotency, replay, out-of-order, and retry evidence cases.`, "amber"],
      ["billing-access-transition-proof.json", `${accessTransitionRows.length} before/after access states for subscription movement.`, "green"],
      ["billing-audit-envelope-proof.json", `${auditEvidenceRows.length} audit envelopes linked to provider event ids.`, "teal"],
    ];
    const backendFields = [
      "webhook_test_pack_id",
      "webhook_blueprint_id",
      "provider_event_id",
      "test_fixture_file",
      "raw_body_hash",
      "signature_header",
      "signature_status",
      "idempotency_status",
      "expected_http_status",
      "actual_http_status",
      "before_subscription_state",
      "after_subscription_state",
      "access_effect_json",
      "audit_event_id",
      "replay_attempt_count",
      "verified_at",
      "verified_by_user_id",
    ];
    const evidenceScore = Math.max(
      35,
      Math.min(
        99,
        Math.round(38 + samplePayloads.length * 5 + signatureProofRows.length * 4 + replayProofRows.length * 3 + evidenceFiles.length * 2),
      ),
    );
    const packet = {
      schemaVersion: "pursuitdesk.webhookTestEvidencePack.v179",
      generatedOn: generatedOn.toISOString(),
      company: companyName,
      evidencePackId,
      sourceBlueprintId: webhookBlueprint.webhookBlueprintId,
      providerAccountId: webhookBlueprint.providerAccountId,
      testClock,
      testSecretRef,
      selectedPlan: membership.label,
      billingTerm: membership.billingTerm,
      currency: billingCurrency(company),
      dueNow: membership.dueNow,
      activeSeats,
      billableSeats: membership.seats,
      summary: {
        evidenceScore,
        samplePayloads: samplePayloads.length,
        signatureProofs: signatureProofRows.length,
        replayProofs: replayProofRows.length,
        accessTransitions: accessTransitionRows.length,
        auditRows: auditEvidenceRows.length,
      },
      samplePayloads,
      signatureProofRows: signatureProofRows.map(([caseName, expected, proof, tone]) => ({ caseName, expected, proof, tone })),
      replayProofRows: replayProofRows.map(([caseName, expected, proof, tone]) => ({ caseName, expected, proof, tone })),
      accessTransitionRows: accessTransitionRows.map(([caseName, transition, proof, tone]) => ({ caseName, transition, proof, tone })),
      auditEvidenceRows,
      evidenceFiles: evidenceFiles.map(([file, note, tone]) => ({ file, note, tone })),
      backendFields,
    };
    return {
      packet,
      evidencePackId,
      evidenceScore,
      testClock,
      samplePayloads,
      signatureProofRows,
      replayProofRows,
      accessTransitionRows,
      auditEvidenceRows,
      evidenceFiles,
      backendFields,
      cards: [
        ["Evidence score", `${evidenceScore}%`, `${samplePayloads.length} payload fixtures and ${auditEvidenceRows.length} audit rows ready for test mode.`, evidenceScore >= 85 ? "green" : "amber"],
        ["Signature proof", signatureProofRows.length, "Valid, tampered, stale, missing, and wrong-tenant signature cases.", "red"],
        ["Replay proof", replayProofRows.length, "First delivery, duplicate replay, out-of-order update, and retry behavior.", "amber"],
        ["Access proof", accessTransitionRows.length, "Before/after access states for billing movement.", "blue"],
      ],
      downloadHref: jsonDataUri(packet),
    };
  }

